import anyio
from httpcore2._backends.anyio import AnyIOStream
from httpcore2._async.connection_pool import AsyncConnectionPool
from httpcore2._utils import is_socket_readable


def install(variant):
    if variant in {'cached_socket', 'combined'}:
        original_init = AnyIOStream.__init__
        original_info = AnyIOStream.get_extra_info
        def initialize(self, stream):
            original_init(self, stream)
            self._audit_socket = stream.extra(anyio.abc.SocketAttribute.raw_socket, None)
        def get_extra_info(self, info):
            if info == 'is_readable':
                return is_socket_readable(self._audit_socket)
            return original_info(self, info)
        AnyIOStream.__init__ = initialize
        AnyIOStream.get_extra_info = get_extra_info
    if variant in {'fused_pool', 'combined'}:
        AsyncConnectionPool._assign_requests_to_connections = assign


def assign(self):
    closing = []
    retained = []
    idle = []
    available = []
    request_connections = {request.connection for request in self._requests}
    for connection in self._connections:
        reserved = connection in request_connections
        if connection.is_closed():
            continue
        if not (connection.is_connected() or reserved):
            continue
        if not reserved and connection.has_expired():
            closing.append(connection)
            continue
        retained.append(connection)
        is_idle = connection.is_idle()
        if is_idle and not reserved:
            idle.append(connection)
        if connection.is_available() and not (is_idle and reserved and not connection.can_multiplex()):
            available.append((connection, is_idle))
    surplus = len(idle) - self._max_keepalive_connections
    if surplus > 0:
        expired = set(idle[:surplus])
        closing.extend(idle[:surplus])
        retained = [connection for connection in retained if connection not in expired]
        available = [(connection, is_idle) for connection, is_idle in available if connection not in expired]
    self._connections = retained
    budget = self._max_connections - len(retained)
    for request in self._requests:
        if not available and budget <= 0:
            break
        if not request.is_queued():
            continue
        origin = request.request.url.origin
        for index, (connection, is_idle) in enumerate(available):
            if connection.can_handle_request(origin):
                request.assign_to_connection(connection)
                if is_idle and not connection.can_multiplex():
                    del available[index]
                break
        else:
            if budget > 0:
                connection = self.create_connection(origin)
                self._connections.append(connection)
                request.assign_to_connection(connection)
                budget -= 1
                continue
            for index, (connection, is_idle) in enumerate(available):
                if is_idle:
                    del available[index]
                    self._connections.remove(connection)
                    closing.append(connection)
                    connection = self.create_connection(origin)
                    self._connections.append(connection)
                    request.assign_to_connection(connection)
                    break
    return closing

