import sys
from pathlib import Path
import typer

sys.path.append('/private/tmp/airmux-httpx2-test-deps')
import pytest

app = typer.Typer()

@app.command()
def run(variant: str = 'baseline'):
    class Patch:
        def pytest_configure(self, config):
            if variant != 'baseline':
                import optimizations
                optimizations.install(variant)
    raise SystemExit(pytest.main(['tests/httpcore2/_async', 'tests/httpcore2/test_cancellations.py', '-q', '-m', 'not network', '--disable-warnings'], plugins=[Patch()]))

if __name__ == '__main__':
    app()
